screenPanels.initJs:
function(container, apiUrl, tables) {
  const proposalTable = tables[0];
  const customerTable = tables[1];
  const constraintTable = tables[2];
  const evaluationTable = tables[3];
  const ruleTable = tables[4];

  let currentProposal = null;
  let evaluationHistory = [];

  // ===== 初期化 =====
  async function init() {
    await loadCustomers();
    await loadEvaluationHistory();
    updateKPIs();
  }

  // ===== 顧客一覧をロード =====
  async function loadCustomers() {
    const customers = await window.aivicApi.list(1); // customerTable
    if (!customers) return;

    const select = container.querySelector('[data-testid="customer-select"]');
    customers.forEach(cust => {
      const opt = document.createElement('option');
      opt.value = cust.id;
      opt.textContent = cust.顧客名 || cust.name;
      select.appendChild(opt);
    });
  }

  // ===== 照合・評価実行 =====
  container.querySelector('[data-testid="evaluate-button"]').addEventListener('click', async () => {
    const customerId = container.querySelector('[data-testid="customer-select"]').value;
    const title = container.querySelector('[data-testid="proposal-title"]').value;
    const amount = parseInt(container.querySelector('[data-testid="proposal-amount"]').value) || 0;
    const content = container.querySelector('[data-testid="proposal-content"]').value;

    if (!customerId || !title || !amount || !content) {
      alert('すべての項目を入力してください');
      return;
    }

    // 提案を保存
    const saved = await window.aivicApi.save(0, {
      顧客ID: customerId,
      提案タイトル: title,
      提案内容: content,
      提案金額: amount,
      ステータス: '下書き'
    });

    if (!saved) return;
    currentProposal = saved;

    // 照合ルール取得
    const rules = await window.aivicApi.list(4);
    const selectedRules = Array.from(container.querySelectorAll('input[name="rule"]:checked')).map(el => el.value);

    // 顧客制約条件取得
    const constraints = await window.aivicApi.list(2);
    const customerConstraints = constraints.filter(c => c.顧客ID === customerId);

    // 簡易的な照合ロジック
    const violations = [];
    let score = 100;

    // 予算チェック
    if (selectedRules.includes('budget')) {
      const budgetConstraint = customerConstraints.find(c => c.制約条件タイプ === '購買金額上限');
      if (budgetConstraint) {
        const limit = parseInt(budgetConstraint.制約値) || 0;
        if (amount > limit) {
          violations.push(`予算超過: 提案金額 ¥${amount.toLocaleString()} > 上限 ¥${limit.toLocaleString()}`);
          score -= 30;
        }
      }
    }

    // 頻度チェック
    if (selectedRules.includes('frequency')) {
      const frequencyConstraint = customerConstraints.find(c => c.制約条件タイプ === '購買頻度制限');
      if (frequencyConstraint) {
        violations.push(`購買頻度制限: ${frequencyConstraint.制約値}`);
        score -= 10;
      }
    }

    score = Math.max(0, score);
    const status = score >= 80 ? '合格' : score >= 60 ? '要確認' : '不合格';

    // 評価結果を保存
    const evaluation = await window.aivicApi.save(3, {
      提案ID: currentProposal.id,
      顧客ID: customerId,
      評価ステータス: status,
      適合性スコア: score,
      照合結果詳細: `提案内容を顧客制約条件と照合しました。${violations.length === 0 ? 'すべての条件を満たしています。' : '以下の項目で制約条件に違反しています。'}`,
      不適合項目: violations.join('\n'),
      評価実施日時: new Date().toISOString()
    });

    if (!evaluation) return;

    // 結果表示
    displayEvaluation(evaluation, violations);
    evaluationHistory.unshift(evaluation);
    updateKPIs();
    updateEvaluationHistory();
  });

  // ===== 評価結果表示 =====
  function displayEvaluation(evaluation, violations) {
    const resultDiv = container.querySelector('#evaluation-result');
    const emptyDiv = container.querySelector('#evaluation-empty');

    container.querySelector('#eval-status').textContent = evaluation.評価ステータス;
    container.querySelector('#eval-score').textContent = `${evaluation.適合性スコア}%`;
    container.querySelector('#eval-detail').textContent = evaluation.照合結果詳細;
    container.querySelector('#eval-violations').textContent = violations.length > 0 ? violations.join('\n') : 'なし';

    resultDiv.style.display = 'block';
    emptyDiv.style.display = 'none';

    // 最終分析結果を更新
    const analysisDiv = container.querySelector('#analysis-result');
    analysisDiv.innerHTML = `
      <div><strong>提案ID:</strong> ${currentProposal.id}</div>
      <div><strong>評価ステータス:</strong> <span style="color: ${evaluation.評価ステータス === '合格' ? '#2e7d32' : evaluation.評価ステータス === '要確認' ? '#f57c00' : '#d32f2f'};">${evaluation.評価ステータス}</span></div>
      <div><strong>適合性スコア:</strong> ${evaluation.適合性スコア}%</div>
      <div style="margin-top: 8px; font-size: 11px; color: var(--text-muted);">評価実施: ${new Date(evaluation.評価実施日時).toLocaleString('ja-JP')}</div>
    `;
  }

  // ===== 修正内容保存 =====
  container.querySelector('[data-testid="save-revision-button"]').addEventListener('click', async () => {
    if (!currentProposal) {
      alert('先に提案を評価してください');
      return;
    }

    const revisedAmount = parseInt(container.querySelector('[data-testid="revised-amount"]').value) || 0;
    const revisionNotes = container.querySelector('[data-testid="revision-notes"]').value;

    if (!revisedAmount || !revisionNotes) {
      alert('修正内容をすべて入力してください');
      return;
    }

    // 修正提案を保存
    const updated = await window.aivicApi.update(0, currentProposal.id, {
      提案金額: revisedAmount,
      ステータス: '修正済み'
    });

    if (updated) {
      alert('修正内容を保存しました');
      container.querySelector('[data-testid="revised-amount"]').value = '';
      container.querySelector('[data-testid="revision-notes"]').value = '';
    }
  });

  // ===== PDF レポート生成 =====
  container.querySelector('[data-testid="generate-report-button"]').addEventListener('click', () => {
    if (!currentProposal) {
      alert('先に提案を評価してください');
      return;
    }

    const reportContent = `
提案管理レポート
================
提案ID: ${currentProposal.id}
提案タイトル: ${currentProposal.提案タイトル}
提案金額: ¥${currentProposal.提案金額.toLocaleString()}
提案内容: ${currentProposal.提案内容}

評価結果:
- ステータス: ${container.querySelector('#eval-status').textContent}
- 適合性スコア: ${container.querySelector('#eval-score').textContent}
- 詳細: ${container.querySelector('#eval-detail').textContent}

生成日時: ${new Date().toLocaleString('ja-JP')}
    `;

    const blob = new Blob([reportContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `proposal-report-${currentProposal.id}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // ===== CSV エクスポート =====
  container.querySelector('[data-testid="export-csv-button"]').addEventListener('click', async () => {
    const proposals = await window.aivicApi.list(0);
    if (!proposals || proposals.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['提案ID', '顧客ID', '提案タイトル', '提案金額', 'ステータス', '作成日時'];
    const rows = proposals.map(p => [
      p.id,
      p.顧客ID,
      p.提案タイトル,
      p.提案金額,
      p.ステータス,
      new Date(p.作成日時).toLocaleString('ja-JP')
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `proposals-${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // ===== 評価履歴表示 =====
  async function loadEvaluationHistory() {
    const evaluations = await window.aivicApi.list(3);
    if (evaluations) {
      evaluationHistory = evaluations.sort((a, b) => new Date(b.評価実施日時) - new Date(a.評価実施日時));
      updateEvaluationHistory();
    }
  }

  function updateEvaluationHistory() {
    const historyDiv = container.querySelector('#evaluation-history');
    if (evaluationHistory.length === 0) {
      historyDiv.innerHTML = '<div style="text-align: center; padding: 20px; color: var(--text-muted); font-size: 12px;">評価履歴はありません</div>';
      return;
    }

    historyDiv.innerHTML = evaluationHistory.slice(0, 10).map((eval, idx) => `
      <div style="display: flex; gap: 10px; padding: 10px; border-left: 2px solid var(--primary); margin-bottom: 8px; background: var(--bg-main); border-radius: 4px;">
        <div style="flex: 1;">
          <div style="font-size: 12px; font-weight: 600; color: var(--text);">提案ID: ${eval.提案ID}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${new Date(eval.評価実施日時).toLocaleString('ja-JP')}</div>
          <div style="font-size: 12px; color: var(--text); margin-top: 4px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${eval.評価ステータス === '合格' ? 'rgba(46,125,50,0.1)' : eval.評価ステータス === '要確認' ? 'rgba(245,127,0,0.1)' : 'rgba(211,47,47,0.1)'}; color: ${eval.評価ステータス === '合格' ? '#2e7d32' : eval.評価ステータス === '要確認' ? '#f57c00' : '#d32f2f'}; font-size: 11px;">
              ${eval.評価ステータス}
            </span>
            <span style="margin-left: 8px; font-size: 11px;">スコア: ${eval.適合性スコア}%</span>
          </div>
        </div>
      </div>
    `).join('');
  }

  // ===== KPI 更新 =====
  async function updateKPIs() {
    const proposals = await window.aivicApi.list(0);
    const evaluations = await window.aivicApi.list(3);

    if (!proposals || !evaluations) return;

    // 当月の提案数
    const now = new Date();
    const currentMonth = proposals.filter(p => {
      const pDate = new Date(p.作成日時);
      return pDate.getFullYear() === now.getFullYear() && pDate.getMonth() === now.getMonth();
    });

    // 平均適合性スコア
    const avgScore = evaluations.length > 0
      ? Math.round(evaluations.reduce((sum, e) => sum + (e.適合性スコア || 0), 0) / evaluations.length)
      : 0;

    // 修正後合格率
    const passCount = evaluations.filter(e => e.評価ステータス === '合格').length;
    const passRate = evaluations.length > 0 ? Math.round((passCount / evaluations.length) * 100) : 0;

    container.querySelector('[data-testid="kpi-proposal-count"]').textContent = currentMonth.length;
    container.querySelector('[data-testid="kpi-avg-score"]').textContent = `${avgScore}%`;
    container.querySelector('[data-testid="kpi-pass-rate"]').textContent = `${passRate}%`;
  }

  init();
}
